/**
 * Central image manifest.
 *
 * `file` is where the real photograph lives (under /public). If that file is
 * missing at build time, the site falls back to `placeholder` — an
 * illustrative mood plate generated by `npm run placeholders` — so the design
 * never shows a broken image. To publish a photograph, add it at `file` and
 * rebuild; no code change is needed.
 */

export type MediaId =
  | "infinityPoolSunset"
  | "villaAerial"
  | "estateOverhead"
  | "dinnerDeckDusk"
  | "firepitLounge"
  | "poolDeckReading"
  | "mistyLawn"
  | "livingRoom"
  | "attractionDiyaluma"
  | "attractionLiptonsSeat"
  | "attractionAdisham"
  | "attractionBambarakanda";

export type MediaEntry = {
  file?: string;
  placeholder: string;
  alt: string;
  /** Focal point for object-position, e.g. "50% 40%". */
  focus?: string;
  /** Short caption for the gallery lightbox. */
  caption: string;
};

